package com.droplists;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Drop Lists",
	description = "Manage toggleable item lists that swap inventory left-click to Drop",
	tags = {"inventory", "drop", "menu", "items"}
)
public class DropListsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private EventBus eventBus;

	@Inject
	private DropListManager dropListManager;

	@Inject
	private MenuEntrySwapService menuEntrySwapService;

	private DropListsPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		eventBus.register(menuEntrySwapService);
		dropListManager.load();

		panel = injector.getInstance(DropListsPanel.class);

		final BufferedImage icon = ImageUtil.loadImageResource(DropListsPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Drop Lists")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		log.debug("Drop Lists started");
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		dropListManager.shutdown();
		eventBus.unregister(menuEntrySwapService);
		log.debug("Drop Lists stopped");
	}

	@Provides
	DropListsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DropListsConfig.class);
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		clientThread.invokeLater(() ->
		{
			dropListManager.load();
			panel.reload();
		});
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		final String listId = panel.getSelectedListId();
		if (listId == null)
		{
			return;
		}

		MenuEntry[] entries = event.getMenuEntries();
		for (int idx = entries.length - 1; idx >= 0; idx--)
		{
			MenuEntry entry = entries[idx];
			Widget widget = entry.getWidget();
			if (widget == null)
			{
				continue;
			}

			if (WidgetUtil.componentToInterface(widget.getId()) != InterfaceID.INVENTORY)
			{
				continue;
			}

			if (!"Examine".equals(entry.getOption()) || entry.getIdentifier() != 10)
			{
				continue;
			}

			int itemId = entry.getItemId();
			if (itemId <= 0)
			{
				itemId = widget.getItemId();
			}
			if (itemId <= 0)
			{
				continue;
			}

			final int finalItemId = itemId;
			String target = entry.getTarget();

			if (dropListManager.listContainsItem(listId, itemId))
			{
				client.createMenuEntry(idx)
					.setOption("Remove from drop list")
					.setTarget(target)
					.setType(MenuAction.RUNELITE)
					.onClick(e -> panel.removeItemFromInventory(finalItemId));
			}
			else
			{
				client.createMenuEntry(idx)
					.setOption("Add to drop list")
					.setTarget(target)
					.setType(MenuAction.RUNELITE)
					.onClick(e -> panel.addItemFromInventory(finalItemId));
			}
			break;
		}
	}
}

package com.droplists;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

@Singleton
class DropListManager
{
	private static final Type LIST_TYPE = new TypeToken<List<DropList>>() {}.getType();

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private ItemManager itemManager;

	@Inject
	private MenuEntrySwapService menuEntrySwapService;

	@Getter
	private final List<DropList> lists = new ArrayList<>();

	void load()
	{
		lists.clear();
		String json = configManager.getConfiguration(DropListsConfig.CONFIG_GROUP, DropListsConfig.LISTS_KEY);
		if (json != null && !json.isEmpty())
		{
			List<DropList> loaded = gson.fromJson(json, LIST_TYPE);
			if (loaded != null)
			{
				lists.addAll(loaded);
			}
		}

		refreshSwaps();
	}

	void save()
	{
		configManager.setConfiguration(DropListsConfig.CONFIG_GROUP, DropListsConfig.LISTS_KEY, gson.toJson(lists));
	}

	DropList createList(String name)
	{
		DropList list = new DropList(UUID.randomUUID().toString(), name, new ArrayList<>(), false);
		lists.add(list);
		save();
		return list;
	}

	String exportList(String listId)
	{
		return findList(listId).map(gson::toJson).orElse(null);
	}

	DropList importList(String data)
	{
		DropList parsed;
		try
		{
			parsed = gson.fromJson(data, DropList.class);
		}
		catch (JsonSyntaxException ex)
		{
			return null;
		}

		if (parsed == null || parsed.getName() == null)
		{
			return null;
		}

		List<Integer> items = parsed.getItemIds() != null
			? new ArrayList<>(parsed.getItemIds())
			: new ArrayList<>();

		DropList list = new DropList(UUID.randomUUID().toString(), parsed.getName(), items, false);
		lists.add(list);
		save();
		return list;
	}

	void deleteList(String listId)
	{
		lists.removeIf(list -> list.getId().equals(listId));
		save();
		refreshSwaps();
	}

	void renameList(String listId, String name)
	{
		findList(listId).ifPresent(list ->
		{
			list.setName(name);
			save();
		});
	}

	void setListEnabled(String listId, boolean enabled)
	{
		findList(listId).ifPresent(list ->
		{
			list.setEnabled(enabled);
			save();
			refreshSwaps();
		});
	}

	void setItems(String listId, List<Integer> itemIds)
	{
		findList(listId).ifPresent(list ->
		{
			List<Integer> deduped = new ArrayList<>();
			for (int itemId : itemIds)
			{
				if (!deduped.contains(itemId))
				{
					deduped.add(itemId);
				}
			}

			list.setItemIds(deduped);
			save();
			refreshSwaps();
		});
	}

	String getItemName(int itemId)
	{
		return itemManager.getItemComposition(itemManager.canonicalize(itemId)).getName();
	}

	boolean listContainsItem(String listId, int itemId)
	{
		int canonicalId = itemManager.canonicalize(itemId);
		return findList(listId).map(list -> list.getItemIds().contains(canonicalId)).orElse(false);
	}

	void removeItem(String listId, int itemId)
	{
		findList(listId).ifPresent(list ->
		{
			if (list.getItemIds().remove(Integer.valueOf(itemManager.canonicalize(itemId))))
			{
				save();
				refreshSwaps();
			}
		});
	}

	void refreshSwaps()
	{
		Set<Integer> activeItems = lists.stream()
			.filter(DropList::isEnabled)
			.flatMap(list -> list.getItemIds().stream())
			.collect(Collectors.toCollection(HashSet::new));
		menuEntrySwapService.applyActiveItems(activeItems);
	}

	void shutdown()
	{
		menuEntrySwapService.clearAll();
	}

	private java.util.Optional<DropList> findList(String listId)
	{
		return lists.stream().filter(list -> list.getId().equals(listId)).findFirst();
	}
}

